#!/usr/bin/env node
/**
 * Post-processes the TypeScript files generated by `lex build` into src/lexicons/.
 *
 * `@atproto/lex` was written for POSIX toolchains and emits broken module specifiers when run
 * on Windows:
 *   - `asRelativePath()` in @atproto/lex-builder passes the result of node:path `relative()`
 *     straight into import strings, so cross-namespace refs come out as
 *     `"./..\\embed\\external.defs"` (backslashes no bundler resolves).
 *   - a stray `--import-ext` value can end up appended to every specifier (e.g. `"./defs''"`).
 *
 * This normalizes `\` to `/` and strips a trailing `''` inside every import/export specifier,
 * touching only the quoted specifier string, never file bodies. It is idempotent, so it is safe
 * to run standalone to repair an already-generated tree without a full reinstall.
 *
 * Wired into the `lexicons:generate` npm script; also runnable directly:
 *   node scripts/fix-lexicon-imports.mjs
 */

import {readdir, readFile, writeFile} from 'node:fs/promises'
import {dirname, join, resolve} from 'node:path'
import {fileURLToPath} from 'node:url'

const LEXICONS_DIR = resolve(
  dirname(fileURLToPath(import.meta.url)),
  '..',
  'src',
  'lexicons',
)

// `from '<spec>'`, `from "<spec>"`, `import('<spec>')` / `import("<spec>")`
// The spec itself may contain the *other* quote char (a stray trailing `''` inside a "…"),
// so match any non-newline char up to the matching closing quote.
const SPECIFIER_RE = /(\bfrom\s+|\bimport\()(['"])((?:(?!\2)[^\n])+?)\2/g

async function* walk(dir) {
  let entries
  try {
    entries = await readdir(dir, {withFileTypes: true})
  } catch (err) {
    if (err.code === 'ENOENT') return
    throw err
  }
  for (const entry of entries) {
    const full = join(entry.parentPath ?? entry.path, entry.name)
    if (entry.isDirectory()) yield* walk(full)
    else if (entry.name.endsWith('.ts')) yield full
  }
}

/** Normalize a single import/export specifier string. */
function fixSpecifier(spec) {
  return spec
    .replace(/\\+/g, '/') // Windows path separators -> POSIX
    .replace(/([^:])\/{2,}/g, '$1/') // collapse `//` (keep protocol `://`, unused here)
    .replace(/''+$/, '') // strip a stray trailing `--import-ext` value
}

let patched = 0
for await (const file of walk(LEXICONS_DIR)) {
  const src = await readFile(file, 'utf8')
  const out = src.replace(
    SPECIFIER_RE,
    (_match, keyword, quote, spec) =>
      `${keyword}${quote}${fixSpecifier(spec)}${quote}`,
  )
  if (out !== src) {
    await writeFile(file, out)
    patched++
  }
}

console.log(`fix-lexicon-imports: ${patched} file(s) patched`)
